{
  "name": "opencode-model-updater",
  "version": "1.3.0",
  "description": "CLI tool to auto-generate OpenCode configuration by fetching models from providers",
  "main": "dist/index.js",
  "bin": {
    "opencode-model-updater": "dist/index.js"
  },
  "scripts": {
    "build": "tsc",
    "start": "node dist/index.js",
    "prepublishOnly": "npm run build"
  },
  "keywords": [
    "opencode",
    "openrouter",
    "model",
    "generator",
    "config",
    "cli",
    "llm",
    "ai"
  ],
  "author": "Barış Kısır",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/bariskisir/OpenCodeModelUpdater.git"
  },
  "homepage": "https://github.com/bariskisir/OpenCodeModelUpdater#readme",
  "bugs": {
    "url": "https://github.com/bariskisir/OpenCodeModelUpdater/issues"
  },
  "dependencies": {
    "commander": "^13.1.0"
  },
  "devDependencies": {
    "@types/node": "^22.15.0",
    "typescript": "^5.8.0"
  },
  "engines": {
    "node": ">=18.0.0"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ]
}
